package com.exelynt.booking.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="resources") public class Resource { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=120) private String name; @Column(length=2000) private String description; @Column(nullable=false,length=60) private String type; @Column(nullable=false,length=120) private String location; @Column(nullable=false,precision=19,scale=2) private BigDecimal price; @Column(nullable=false) private boolean available=true; @Column(nullable=false,updatable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; @PrePersist void create(){createdAt=updatedAt=Instant.now();}@PreUpdate void update(){updatedAt=Instant.now();} public Long getId(){return id;} public String getName(){return name;} public String getDescription(){return description;} public String getType(){return type;} public String getLocation(){return location;} public BigDecimal getPrice(){return price;} public boolean isAvailable(){return available;} public void setName(String v){name=v;} public void setDescription(String v){description=v;} public void setType(String v){type=v;} public void setLocation(String v){location=v;} public void setPrice(BigDecimal v){price=v;} public void setAvailable(boolean v){available=v;} }
